66	/**
67	 * The default {@link S3ClientFactory} implementation.
68	 * This calls the AWS SDK to configure and create an
69	 * {@code AmazonS3Client} that communicates with the S3 service.
70	 */
71	@InterfaceAudience.Private
72	@InterfaceStability.Unstable
73	public class DefaultS3ClientFactory extends Configured
74	    implements S3ClientFactory {
75	
76	  private static final String S3_SERVICE_NAME = "s3";
77	
78	  /**
79	   * Subclasses refer to this.
80	   */
81	  protected static final Logger LOG =
82	      LoggerFactory.getLogger(DefaultS3ClientFactory.class);
83	
84	  /**
85	   * A one-off warning of default region chains in use.
86	   */
87	  private static final LogExactlyOnce WARN_OF_DEFAULT_REGION_CHAIN =
88	      new LogExactlyOnce(LOG);
89	
90	  /**
91	   * Warning message printed when the SDK Region chain is in use.
92	   */
93	  private static final String SDK_REGION_CHAIN_IN_USE =
94	      "S3A filesystem client is using"
95	          + " the SDK region resolution chain.";
96	
97	  /** Exactly once log to inform about ignoring the AWS-SDK Warnings for CSE. */
98	  private static final LogExactlyOnce IGNORE_CSE_WARN = new LogExactlyOnce(LOG);
99	
100	  /** Bucket name. */
101	  private String bucket;
102	
103	  /**
104	   * Create the client by preparing the AwsConf configuration
105	   * and then invoking {@code buildAmazonS3Client()}.
106	   */
107	  @Override
108	  public AmazonS3 createS3Client(
109	      final URI uri,
110	      final S3ClientCreationParameters parameters) throws IOException {
111	    Configuration conf = getConf();
112	    bucket = uri.getHost();
113	    final ClientConfiguration awsConf = S3AUtils
114	        .createAwsConf(conf,
115	            bucket,
116	            Constants.AWS_SERVICE_IDENTIFIER_S3);
117	    // add any headers
118	    parameters.getHeaders().forEach((h, v) ->
119	        awsConf.addHeader(h, v));
120	
121	    // When EXPERIMENTAL_AWS_INTERNAL_THROTTLING is false
122	    // throttling is explicitly disabled on the S3 client so that
123	    // all failures are collected in S3A instrumentation, and its
124	    // retry policy is the only one used.
125	    // This may cause problems in copy/rename.
126	    awsConf.setUseThrottleRetries(
127	        conf.getBoolean(EXPERIMENTAL_AWS_INTERNAL_THROTTLING,
128	            EXPERIMENTAL_AWS_INTERNAL_THROTTLING_DEFAULT));
129	
130	    if (!StringUtils.isEmpty(parameters.getUserAgentSuffix())) {
131	      awsConf.setUserAgentSuffix(parameters.getUserAgentSuffix());
132	    }
133	
134	    // Get the encryption method for this bucket.
135	    S3AEncryptionMethods encryptionMethods =
136	        getEncryptionAlgorithm(bucket, conf);
137	    try {
138	      // If CSE is enabled then build a S3EncryptionClient.
139	      if (S3AEncryptionMethods.CSE_KMS.getMethod()
140	          .equals(encryptionMethods.getMethod())) {
141	        return buildAmazonS3EncryptionClient(
142	            awsConf,
143	            parameters);
144	      } else {
145	        return buildAmazonS3Client(
146	            awsConf,
147	            parameters);
148	      }
149	    } catch (SdkClientException e) {
150	      // SDK refused to build.
151	      throw translateException("creating AWS S3 client", uri.toString(), e);
152	    }
153	  }
154	
155	  /**
156	   * Create an {@link AmazonS3} client of type
157	   * {@link AmazonS3EncryptionV2} if CSE is enabled.
158	   *
159	   * @param awsConf    AWS configuration.
160	   * @param parameters parameters.
161	   *
162	   * @return new AmazonS3 client.
163	   * @throws IOException if lookupPassword() has any problem.
164	   */
165	  protected AmazonS3 buildAmazonS3EncryptionClient(
166	      final ClientConfiguration awsConf,
167	      final S3ClientCreationParameters parameters) throws IOException {
168	
169	    AmazonS3 client;
170	    AmazonS3EncryptionClientV2Builder builder =
171	        new AmazonS3EncryptionClientV2Builder();
172	    Configuration conf = getConf();
173	
174	    // CSE-KMS Method
175	    String kmsKeyId = getS3EncryptionKey(bucket, conf, true);
176	    // Check if kmsKeyID is not null
177	    Preconditions.checkArgument(!StringUtils.isBlank(kmsKeyId), "CSE-KMS "
178	        + "method requires KMS key ID. Use " + S3_ENCRYPTION_KEY
179	        + " property to set it. ");
180	
181	    EncryptionMaterialsProvider materialsProvider =
182	        new KMSEncryptionMaterialsProvider(kmsKeyId);
183	    builder.withEncryptionMaterialsProvider(materialsProvider);
184	    //Configure basic params of a S3 builder.
185	    configureBasicParams(builder, awsConf, parameters);
186	
187	    // Configuring endpoint.
188	    AmazonS3EncryptionClientV2Builder.EndpointConfiguration epr
189	        = createEndpointConfiguration(parameters.getEndpoint(),
190	        awsConf, getConf().getTrimmed(AWS_REGION));
191	    configureEndpoint(builder, epr);
192	
193	    // Create cryptoConfig.
194	    CryptoConfigurationV2 cryptoConfigurationV2 =
195	        new CryptoConfigurationV2(CryptoMode.AuthenticatedEncryption)
196	            .withRangeGetMode(CryptoRangeGetMode.ALL);
197	    if (epr != null) {
198	      cryptoConfigurationV2
199	          .withAwsKmsRegion(RegionUtils.getRegion(epr.getSigningRegion()));
200	      LOG.debug("KMS region used: {}", cryptoConfigurationV2.getAwsKmsRegion());
201	    }
202	    builder.withCryptoConfiguration(cryptoConfigurationV2);
203	    client = builder.build();
204	    IGNORE_CSE_WARN.info("S3 client-side encryption enabled: Ignore S3-CSE "
205	        + "Warnings.");
206	
207	    return client;
208	  }
