210	  /**
211	   * Use the Builder API to create an AWS S3 client.
212	   * <p>
213	   * This has a more complex endpoint configuration mechanism
214	   * which initially caused problems; the
215	   * {@code withForceGlobalBucketAccessEnabled(true)}
216	   * command is critical here.
217	   * @param awsConf  AWS configuration
218	   * @param parameters parameters
219	   * @return new AmazonS3 client
220	   * @throws SdkClientException if the configuration is invalid.
221	   */
222	  protected AmazonS3 buildAmazonS3Client(
223	      final ClientConfiguration awsConf,
224	      final S3ClientCreationParameters parameters) {
225	    AmazonS3ClientBuilder b = AmazonS3Client.builder();
226	    configureBasicParams(b, awsConf, parameters);
227	
228	    // endpoint set up is a PITA
229	    AwsClientBuilder.EndpointConfiguration epr
230	        = createEndpointConfiguration(parameters.getEndpoint(),
231	        awsConf, getConf().getTrimmed(AWS_REGION));
232	    configureEndpoint(b, epr);
233	    final AmazonS3 client = b.build();
234	    return client;
235	  }
236	
237	  /**
238	   * A method to configure basic AmazonS3Builder parameters.
239	   *
240	   * @param builder    Instance of AmazonS3Builder used.
241	   * @param awsConf    ClientConfiguration used.
242	   * @param parameters Parameters used to set in the builder.
243	   */
244	  private void configureBasicParams(AmazonS3Builder builder,
245	      ClientConfiguration awsConf, S3ClientCreationParameters parameters) {
246	    builder.withCredentials(parameters.getCredentialSet());
247	    builder.withClientConfiguration(awsConf);
248	    builder.withPathStyleAccessEnabled(parameters.isPathStyleAccess());
249	
250	    if (parameters.getMetrics() != null) {
251	      builder.withMetricsCollector(
252	          new AwsStatisticsCollector(parameters.getMetrics()));
253	    }
254	    if (parameters.getRequestHandlers() != null) {
255	      builder.withRequestHandlers(
256	          parameters.getRequestHandlers().toArray(new RequestHandler2[0]));
257	    }
258	    if (parameters.getMonitoringListener() != null) {
259	      builder.withMonitoringListener(parameters.getMonitoringListener());
260	    }
261	
262	  }
263	
264	  /**
265	   * A method to configure endpoint and Region for an AmazonS3Builder.
266	   *
267	   * @param builder Instance of AmazonS3Builder used.
268	   * @param epr     EndpointConfiguration used to set in builder.
269	   */
270	  private void configureEndpoint(
271	      AmazonS3Builder builder,
272	      AmazonS3Builder.EndpointConfiguration epr) {
273	    if (epr != null) {
274	      // an endpoint binding was constructed: use it.
275	      builder.withEndpointConfiguration(epr);
276	    } else {
277	      // no idea what the endpoint is, so tell the SDK
278	      // to work it out at the cost of an extra HEAD request
279	      builder.withForceGlobalBucketAccessEnabled(true);
280	      // HADOOP-17771 force set the region so the build process doesn't halt.
281	      String region = getConf().getTrimmed(AWS_REGION, AWS_S3_CENTRAL_REGION);
282	      LOG.debug("fs.s3a.endpoint.region=\"{}\"", region);
283	      if (!region.isEmpty()) {
284	        // there's either an explicit region or we have fallen back
285	        // to the central one.
286	        LOG.debug("Using default endpoint; setting region to {}", region);
287	        builder.setRegion(region);
