332	  /**
333	   * Given an endpoint string, return an endpoint config, or null, if none
334	   * is needed.
335	   * <p>
336	   * This is a pretty painful piece of code. It is trying to replicate
337	   * what AwsClient.setEndpoint() does, because you can't
338	   * call that setter on an AwsClient constructed via
339	   * the builder, and you can't pass a metrics collector
340	   * down except through the builder.
341	   * <p>
342	   * Note also that AWS signing is a mystery which nobody fully
343	   * understands, especially given all problems surface in a
344	   * "400 bad request" response, which, like all security systems,
345	   * provides minimal diagnostics out of fear of leaking
346	   * secrets.
347	   *
348	   * @param endpoint possibly null endpoint.
349	   * @param awsConf config to build the URI from.
350	   * @param awsRegion AWS S3 Region if the corresponding config is set.
351	   * @return a configuration for the S3 client builder.
352	   */
353	  @VisibleForTesting
354	  public static AwsClientBuilder.EndpointConfiguration
355	      createEndpointConfiguration(
356	      final String endpoint, final ClientConfiguration awsConf,
357	      String awsRegion) {
358	    LOG.debug("Creating endpoint configuration for \"{}\"", endpoint);
359	    if (endpoint == null || endpoint.isEmpty()) {
360	      // the default endpoint...we should be using null at this point.
361	      LOG.debug("Using default endpoint -no need to generate a configuration");
362	      return null;
363	    }
364	
365	    final URI epr = RuntimeHttpUtils.toUri(endpoint, awsConf);
366	    LOG.debug("Endpoint URI = {}", epr);
367	    String region = awsRegion;
368	    if (StringUtils.isBlank(region)) {
369	      if (!ServiceUtils.isS3USStandardEndpoint(endpoint)) {
370	        LOG.debug("Endpoint {} is not the default; parsing", epr);
371	        region = AwsHostNameUtils.parseRegion(
372	            epr.getHost(),
373	            S3_SERVICE_NAME);
374	      } else {
375	        // US-east, set region == null.
376	        LOG.debug("Endpoint {} is the standard one; declare region as null",
377	            epr);
378	        region = null;
379	      }
380	    }
381	    LOG.debug("Region for endpoint {}, URI {} is determined as {}",
382	        endpoint, epr, region);
383	    return new AwsClientBuilder.EndpointConfiguration(endpoint, region);
384	  }
